public class OwnSourceDocReader {

    /** Provided -- do not edit. The file this class reads at run time. */
    static final String SOURCE_FILE = "OwnSourceDocReader.java";

    /**
     * Returns the names on the @param tags of the doc comment that sits directly
     * above the declaration of the named method in this very file.
     *
     * @param methodName the method to look up
     * @return the documented parameter names, in order
     */
    public static java.util.List<String> documentedParamsOf(String methodName) {
        java.util.List<String> names = new java.util.ArrayList<>();
        if (methodName == null || methodName.isEmpty()) {
            return names;
        }

        String[] lines;
        try {
            String text = java.nio.file.Files.readString(java.nio.file.Path.of(SOURCE_FILE));
            lines = text.split("\n", -1);
        } catch (java.io.IOException e) {
            return names;
        }

        int declaration = -1;
        for (int i = 0; i < lines.length; i++) {
            String line = lines[i].trim();
            boolean isDeclaration = line.startsWith("public ")
                    || line.startsWith("private ")
                    || line.startsWith("static ");
            if (isDeclaration && line.contains(methodName + "(")) {
                declaration = i;
                break;
            }
        }
        if (declaration < 0) {
            return names;
        }

        int end = declaration - 1;
        while (end >= 0 && lines[end].trim().isEmpty()) {
            end--;
        }
        if (end < 0 || !lines[end].trim().endsWith("*/")) {
            return names;
        }

        int start = -1;
        for (int i = end; i >= 0; i--) {
            String line = lines[i].trim();
            if (line.startsWith("/**")) {
                start = i;
                break;
            }
            if (line.startsWith("/*")) {
                return names;
            }
        }
        if (start < 0) {
            return names;
        }

        for (int i = start; i <= end; i++) {
            String line = lines[i].trim();
            if (line.startsWith("*")) {
                line = line.substring(1).trim();
            }
            if (!line.startsWith("@param ")) {
                continue;
            }
            String rest = line.substring("@param ".length()).trim();
            int space = rest.indexOf(' ');
            names.add(space < 0 ? rest : rest.substring(0, space));
        }
        return names;
    }

    /**
     * Provided sample -- do not edit.
     *
     * @param lowerBound the smallest allowed value
     * @param upperBound the largest allowed value
     * @return the midpoint of the range
     */
    public static int clampSample(int lowerBound, int upperBound) {
        return (lowerBound + upperBound) / 2;
    }

    /* Provided sample -- do not edit. A plain block comment is not documentation. */
    public static int plainlyCommentedSample(int seed) {
        return seed;
    }

    // Provided sample -- do not edit. This one has no comment above it at all.
    public static int undocumentedSample(int seed) {
        return seed + 1;
    }
}
